using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using PA.Tickets.Application.Tickets;using PA.Tickets.Domain.Tickets;
namespace PA.Tickets.Api.Controllers;
[ApiController,Authorize,Route("api/v1/tickets")]
[Asp.Versioning.ApiVersion("1.0")]
public sealed class TicketsController(ITicketLifecycleService service):ControllerBase
{
 [HttpGet] public Task<TicketSearchPage> Search([FromQuery]string? number,[FromQuery]TicketStatus? status,[FromQuery]TicketType? type,[FromQuery]long? priorityId,[FromQuery]long? serviceId,[FromQuery]long? categoryId,[FromQuery]long? requestTypeId,[FromQuery]long? clientId,[FromQuery]long? departmentId,[FromQuery]long? teamId,[FromQuery]long? assigneeId,[FromQuery]DateTimeOffset? createdFrom,[FromQuery]DateTimeOffset? createdTo,[FromQuery]int page=1,[FromQuery]int pageSize=25,CancellationToken ct=default)=>service.SearchAsync(new(number,status,type,priorityId,serviceId,categoryId,requestTypeId,clientId,departmentId,teamId,assigneeId,createdFrom,createdTo,page,pageSize),Actor(),ct);
 [HttpGet("lookup/{identifier}")] public Task<TicketView> Lookup(string identifier,CancellationToken ct)=>service.LookupAsync(identifier,Actor(),ct);
 [HttpGet("{id:long}")]public Task<TicketView> Get(long id,CancellationToken ct)=>service.GetAsync(id,Actor(),ct);
 [HttpPost]public async Task<ActionResult<TicketView>> Create(CreateTicketRequest r,[FromHeader(Name = "Idempotency-Key")] string? idempotencyKey,CancellationToken ct){ if(string.IsNullOrWhiteSpace(idempotencyKey)) return BadRequest(new { title = "Idempotency-Key is required." }); var created=await service.CreateAsync(new(r.Type,r.Subject,r.Description,Actor(),Actor(),r.RequestTypeId,r.FieldValues?.Select(x=>new PA.Tickets.Application.Foundations.TicketFieldValue(x.FieldId,x.StringValue,x.NumberValue,x.DateValue,x.TextValue)).ToArray(),idempotencyKey,r.ServiceId,r.CategoryId,r.SubCategoryId),ct); return created; }
 [HttpPost("{id:long}/classify")]public Task<TicketView> Classify(long id,ClassificationRequest r,CancellationToken ct)=>service.ClassifyAsync(id,r.ServiceId,r.CategoryId,r.RequestTypeId,r.PriorityId,Actor(),ct);
 [HttpPost("{id:long}/route")]public Task<TicketView> Route(long id,RouteRequest r,CancellationToken ct)=>service.RouteAsync(id,r.DepartmentId,r.TeamId,Actor(),ct);
 [HttpPost("{id:long}/approval")]public Task<TicketView> RequestApproval(long id,ApprovalRequest r,CancellationToken ct)=>service.RequestApprovalAsync(id,r.ApproverUserId,Actor(),ct);
 [HttpPost("{id:long}/approve")]public Task<TicketView> Approve(long id,CancellationToken ct)=>service.ApproveAsync(id,Actor(),ct);
 [HttpPost("{id:long}/work-items/{workItemId:long}/execute")]public Task<TicketView> Execute(long id,long workItemId,ExecuteRequest r,CancellationToken ct)=>service.ExecuteAsync(id,workItemId,r.ExecutorUserId,Actor(),ct);
 [HttpPost("{id:long}/work-items/{workItemId:long}/reassign")]public Task<TicketView> Reassign(long id,long workItemId,AssignmentRequest r,CancellationToken ct)=>service.ReassignAsync(id,workItemId,r.AssigneeUserId,Actor(),r.Reason,ct);
 [HttpPost("{id:long}/work-items/{workItemId:long}/wait")]public Task<TicketView> Wait(long id,long workItemId,WaitRequest r,CancellationToken ct)=>service.WaitAsync(id,workItemId,new(r.Reason,r.Comment,r.EvidenceReference,r.ExpectedDate),Actor(),ct);
 [HttpPost("{id:long}/work-items/{workItemId:long}/resume")]public Task<TicketView> Resume(long id,long workItemId,CancellationToken ct)=>service.ResumeAsync(id,workItemId,Actor(),ct);
 [HttpPost("{id:long}/evidence")]public Task<TicketView> Evidence(long id,CancellationToken ct)=>service.AddEvidenceAsync(id,Actor(),ct);
 [HttpPost("{id:long}/work-items/{workItemId:long}/complete")]public Task<TicketView> Complete(long id,long workItemId,CancellationToken ct)=>service.CompleteWorkAsync(id,workItemId,Actor(),ct);
 [HttpPost("{id:long}/resolve")]public Task<TicketView> Resolve(long id,CancellationToken ct)=>service.ResolveAsync(id,Actor(),ct);
 [HttpPost("{id:long}/reopen")]public Task<TicketView> Reopen(long id,ReasonRequest r,CancellationToken ct)=>service.ReopenAsync(id,r.Reason,Actor(),ct);
 [HttpPost("{id:long}/cancel")]public Task<TicketView> Cancel(long id,ReasonRequest r,CancellationToken ct)=>service.CancelAsync(id,r.Reason,Actor(),ct);
 [HttpPost("{id:long}/close")]public Task<TicketView> Close(long id,CancellationToken ct)=>service.CloseAsync(id,Actor(),ct);
 [HttpPost("{id:long}/relationships")]public Task<TicketRelationship> Relate(long id,RelationshipRequest r,CancellationToken ct)=>service.AddRelationshipAsync(id,r.RelatedTicketId,r.RelationType,r.Description,Actor(),ct);
 private long Actor(){var raw=User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub");if(!long.TryParse(raw,out var id)||id<=0)throw new UnauthorizedAccessException("The authenticated subject must map to a PA Tickets user.");return id;}
}
public sealed record CreateTicketRequest(TicketType Type,string Subject,string? Description,long? RequestTypeId=null,IReadOnlyCollection<TicketFieldValueRequest>? FieldValues=null,long? ServiceId=null,long? CategoryId=null,long? SubCategoryId=null);public sealed record TicketFieldValueRequest(long FieldId,string? StringValue,decimal? NumberValue,DateTimeOffset? DateValue,string? TextValue);public sealed record ClassificationRequest(long ServiceId,long CategoryId,long RequestTypeId,long PriorityId);public sealed record RouteRequest(long? DepartmentId,long? TeamId);public sealed record ApprovalRequest(long ApproverUserId);public sealed record ExecuteRequest(long ExecutorUserId);public sealed record AssignmentRequest(long AssigneeUserId,string? Reason);public sealed record WaitRequest(string Reason,string? Comment,string? EvidenceReference,DateTimeOffset? ExpectedDate);public sealed record ReasonRequest(string Reason);public sealed record RelationshipRequest(long RelatedTicketId,string RelationType,string? Description);
